SELECT id, operator_id, action, object_type, object_id, before_summary, after_summary, result, trace_id,
       created_at, client_ip, user_agent, request_method, request_uri, session_id
FROM operation_log WHERE 1 = 1
AND operator_id = #{operatorId}
AND action = #{action}
AND object_type = #{objectType}
AND result = #{result}
AND created_at >= #{fromInclusive}
AND created_at < #{toExclusive}
ORDER BY created_at DESC, id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM operation_log WHERE 1 = 1
AND operator_id = #{operatorId}
AND action = #{action}
AND object_type = #{objectType}
AND result = #{result}
AND created_at >= #{fromInclusive}
AND created_at < #{toExclusive}

SELECT id, operator_id, action, object_type, object_id, before_summary, after_summary, result, trace_id,
       created_at, client_ip, user_agent, request_method, request_uri, session_id
FROM operation_log WHERE id = #{id}
